+    private static function render_list($product) {
+        $products = self::products();
+        echo '<p>' . esc_html__('Tell the makers of the wpallstars plugins and themes on this site about a problem or an improvement, so every site using them gets the fix. Your AI assistant can draft reports too (the wpallstars/report-problem ability, or wp wpallstars report create); nothing leaves the site until an administrator sends it here.', 'seoprocookieconsent') . '</p>';
+        echo '<ul class="ul-disc">';
+        foreach ($products as $slug => $item) {
+            printf(
+                '<li>%1$s: %2$s</li>',
