+                esc_html(self::channel_label($item))
+            );
+        }
+        echo '</ul>';
+
+        $reports = self::reports();
+        if (!$reports) {
+            echo '<p>' . esc_html__('No reports yet.', 'seoprocookieconsent') . '</p>';
+            return;
+        }
+        echo '<table class="widefat striped"><thead><tr>';
+        foreach (array(__('Title', 'seoprocookieconsent'), __('Plugin or theme', 'seoprocookieconsent'), __('Type', 'seoprocookieconsent'), __('Status', 'seoprocookieconsent'), __('Drafted by', 'seoprocookieconsent'), __('Date', 'seoprocookieconsent')) as $heading) {
+            echo '<th scope="col">' . esc_html($heading) . '</th>';
+        }
+        echo '</tr></thead><tbody>';
+        foreach ($reports as $report) {
+            $name = isset($products[$report['product']]) ? $products[$report['product']]['name'] : $report['product'];
+            echo '<tr>';
+            echo '<td><a href="' . esc_url(self::url($report['id'])) . '"><strong>' . esc_html($report['title']) . '</strong></a></td>';
+            echo '<td>' . esc_html($name) . '</td>';
