+
+    /**
+     * A report's status, in words.
+     *
+     * @param array $report Report.
+     * @return string
+     */
+    private static function status_label(array $report) {
+        if ('sent' !== $report['status']) {
+            return __('Draft, waiting for review', 'seoprocookieconsent');
+        }
+        $when = (string) wp_date((string) get_option('date_format'), (int) $report['sent']);
+        if ('github' === $report['channel']) {
+            /* translators: %s: date. */
+            return sprintf(__('Opened on GitHub %s', 'seoprocookieconsent'), $when);
+        }
+        /* translators: %s: date. */
+        return sprintf(__('Emailed %s', 'seoprocookieconsent'), $when);
